CREATE OR REPLACE FUNCTION public.club_has_access(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user_id,'admin') OR EXISTS(SELECT 1 FROM public.clube_hs_subscriptions WHERE user_id=_user_id AND status='authorized') OR EXISTS(SELECT 1 FROM public.clube_hs_pix_payments WHERE user_id=_user_id AND status='approved' AND expires_at>now()) OR EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=_user_id AND p.is_clube_hs AND NOT EXISTS(SELECT 1 FROM public.clube_hs_pix_payments WHERE user_id=_user_id AND status='approved') AND NOT EXISTS(SELECT 1 FROM public.clube_hs_subscriptions WHERE user_id=_user_id)); $$;
REVOKE ALL ON FUNCTION public.club_has_access(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.club_has_access(uuid) TO authenticated,service_role;
CREATE POLICY social_chat_media_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id='social-stories' AND (EXISTS(SELECT 1 FROM public.social_messages m WHERE m.media_path=objects.name) OR EXISTS(SELECT 1 FROM public.social_group_messages m WHERE m.media_path=objects.name)));
CREATE POLICY social_chat_audio_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='social-stories' AND (storage.foldername(name))[1]=auth.uid()::text AND lower(storage.extension(name)) IN ('webm','ogg','m4a','mp3','wav') AND public.club_has_access(auth.uid()));
CREATE TABLE public.social_presence(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,last_seen_at timestamptz NOT NULL DEFAULT now(),typing_conversation_id uuid REFERENCES public.social_conversations(id) ON DELETE SET NULL,typing_at timestamptz);
GRANT SELECT ON public.social_presence TO authenticated;
GRANT ALL ON public.social_presence TO service_role;
ALTER TABLE public.social_presence ENABLE ROW LEVEL SECURITY;
CREATE POLICY social_presence_contact_read ON public.social_presence FOR SELECT TO authenticated USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.social_conversations c WHERE auth.uid() IN(c.member_a,c.member_b) AND social_presence.user_id IN(c.member_a,c.member_b)));
CREATE OR REPLACE FUNCTION public.social_heartbeat() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na sua conta.'; END IF; INSERT INTO public.social_presence(user_id,last_seen_at) VALUES(auth.uid(),now()) ON CONFLICT(user_id) DO UPDATE SET last_seen_at=now(); END $$;
CREATE OR REPLACE FUNCTION public.social_set_typing(_conversation_id uuid,_typing boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.social_conversations WHERE id=_conversation_id AND auth.uid() IN(member_a,member_b)) THEN RAISE EXCEPTION 'Conversa não disponível.'; END IF; INSERT INTO public.social_presence(user_id,last_seen_at,typing_conversation_id,typing_at) VALUES(auth.uid(),now(),CASE WHEN _typing THEN _conversation_id END,CASE WHEN _typing THEN now() END) ON CONFLICT(user_id) DO UPDATE SET typing_conversation_id=CASE WHEN _typing THEN _conversation_id END,typing_at=CASE WHEN _typing THEN now() END; END $$;
REVOKE ALL ON FUNCTION public.social_heartbeat(),public.social_set_typing(uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.social_heartbeat(),public.social_set_typing(uuid,boolean) TO authenticated;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='social_presence') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.social_presence; END IF; IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='social_group_messages') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.social_group_messages; END IF; END $$;